const DEFAULT={version:4,lang:'id',theme:'light',focus:false,view:'home',activeModule:'m1',activeGuide:'g01',activeCase:'cas1',completedModules:[],readProgress:{},quizAttempts:[],labAttempts:[],completedLabs:[],notes:{},journal:'',studyDates:[],activity:[],glossarySeen:[],lastSavedAt:null};
let state=JSON.parse(JSON.stringify(DEFAULT)),runtime={refSearch:'',activeReference:'pam',libraryMode:'articles',activeSource:'',quiz:null,quizResult:null,caseResult:null,glossaryReveal:new Set(),curriculumSearch:'',guideSearch:'',termSearch:'',noteModule:'journal'},serverSync=false,saveTimer=0;
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s)),copy=()=>UI[state.lang],clone=x=>JSON.parse(JSON.stringify(x)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=o=>typeof o==='string'?o:(o?.[state.lang]??o?.id??o?.en??''),modules=()=>Object.values(COURSE.modules).sort((a,b)=>a.order-b.order),questions=()=>COURSE.questionBank||[],cases=()=>Object.entries(COURSE.cases).map(([key,value])=>({...value,key})),mod=id=>COURSE.modules[id],guide=id=>COURSE.guides.find(x=>x.id===id)||COURSE.guides[0],caseData=id=>COURSE.cases[id]?({...COURSE.cases[id],key:id}):cases()[0],title=m=>state.lang==='id'?m.title:m.en,phase=m=>state.lang==='id'?m.phase:m.phaseEn,complete=id=>state.completedModules.includes(id),percent=id=>Math.round((state.readProgress[id]||0)*100),today=()=>new Date().toISOString().slice(0,10),unique=a=>Array.from(new Set(a));
function date(iso){if(!iso)return '—';try{return new Intl.DateTimeFormat(state.lang==='id'?'id-ID':'en-US',{dateStyle:'medium',timeStyle:'short'}).format(new Date(iso))}catch{return iso}}
function merge(raw){const next=clone(DEFAULT);if(raw&&typeof raw==='object')Object.keys(next).forEach(k=>{if(raw[k]!==undefined)next[k]=raw[k]});next.completedModules=Array.isArray(next.completedModules)?unique(next.completedModules.filter(id=>mod(id))):[];next.completedLabs=Array.isArray(next.completedLabs)?unique(next.completedLabs.map(x=>typeof x==='string'?x:(typeof x?.key==='string'?x.key:null)).filter(id=>COURSE.cases[id])):[];next.readProgress=next.readProgress&&typeof next.readProgress==='object'?next.readProgress:{};next.notes=next.notes&&typeof next.notes==='object'?next.notes:{};next.quizAttempts=Array.isArray(next.quizAttempts)?next.quizAttempts.slice(0,100):[];next.activity=Array.isArray(next.activity)?next.activity.slice(0,80):[];return next}
async function load(){let raw=null;if(location.protocol==='http:'&&['127.0.0.1','localhost'].includes(location.hostname)){try{const r=await fetch('/api/progress',{cache:'no-store'});if(r.ok){raw=(await r.json()).data;serverSync=true}}catch{}}if(!raw){try{raw=JSON.parse(localStorage.getItem('cyberark-l2-rolebook-v4')||'null')}catch{}}if(!raw){try{const legacy=JSON.parse(localStorage.getItem('cyberarkMastercourseV1')||'null');if(legacy)raw={version:4,lang:legacy.lang||'id',theme:legacy.theme||'light',completedModules:Array.isArray(legacy.completed)?legacy.completed:[],journal:legacy.notes||''}}catch{}}state=merge(raw);state.view='home';prefs();study(false);syncLabel();render()}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{state.lastSavedAt=new Date().toISOString();try{localStorage.setItem('cyberark-l2-rolebook-v4',JSON.stringify(state))}catch{}if(serverSync){try{const r=await fetch('/api/progress',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)});if(!r.ok)throw Error()}catch{serverSync=false}}syncLabel()},350)}
function study(log=true){if(!state.studyDates.includes(today()))state.studyDates.push(today());if(log)activity('study',state.lang==='id'?'Sesi belajar dimulai':'Study session started');save()}
function activity(type,text){state.activity.unshift({type,text,date:new Date().toISOString()});state.activity=state.activity.slice(0,80);if(!state.studyDates.includes(today()))state.studyDates.push(today());save()}
function prefs(){document.documentElement.dataset.theme=state.theme;document.documentElement.lang=state.lang;document.body.classList.toggle('focus-mode',state.focus);const f=$('#focusBtn'),t=$('#themeBtn');if(f){f.textContent='◐ '+(state.focus?copy().focusOff:copy().focusOn);f.setAttribute('aria-pressed',String(state.focus))}if(t){t.textContent=(state.theme==='dark'?'☀ ':'☾ ')+(state.theme==='dark'?copy().themeLight:copy().themeDark);t.setAttribute('aria-pressed',String(state.theme==='dark'))}$$('[data-action="lang"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===state.lang)))}
function syncLabel(){const e=$('#syncLabel'),l=$('#lastSavedLabel');if(e)e.textContent=serverSync?copy().folderSync:copy().browserOnly;if(l)l.textContent=state.lastSavedAt?copy().lastSaved+': '+date(state.lastSavedAt):'';$('#syncDot')?.classList.toggle('online',serverSync)}
function toast(text,type='ok'){const r=$('#toastRegion');if(!r)return;const x=document.createElement('div');x.className='toast '+type;x.textContent=text;r.appendChild(x);setTimeout(()=>x.remove(),3500)}
function nav(view){runtime.quiz=null;runtime.quizResult=null;runtime.caseResult=null;state.view=view;render();$('#mainContent')?.focus();save()}
function renderNav(){const n=$('#mainNav');n.innerHTML='<div class="nav-label">'+esc(copy().learningPath)+'</div>'+NAV.map(([id,icon])=>`<button class="nav-btn" data-action="nav" data-view="${id}" aria-current="${state.view===id}"><span class="nav-icon" aria-hidden="true">${icon}</span><span>${esc(copy()[id])}</span></button>`).join('')}
function shell(){renderNav();prefs();syncLabel();const names={home:copy().courseHome,curriculum:copy().curriculum,reader:title(mod(state.activeModule)),library:copy().library,practice:copy().practice,scenarios:copy().scenarios,playbooks:copy().playbooks,glossary:copy().glossary,notes:copy().notes,progress:copy().progress};$('#topTitle').textContent=names[state.view]||copy().courseHome}
function renderGate(){return `<div class="welcome-gate"><div class="welcome-card card card-pad"><div class="brand-mark" style="margin-bottom:20px"><svg viewBox="0 0 24 24" width="32" height="32" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M4 6H9.5C11.5 6 13 7.5 13 9.5C13 11.5 11.5 13 9.5 13H6V18H4V6Z" fill="#fff"/><path d="M15 6L20 18H17.5L16.25 15H11.75L10.5 18H8L13 6H15ZM15.5 13L14 9.5L12.5 13H15.5Z" fill="var(--brand)"/></svg><span style="font-size:1.3rem;font-weight:900;letter-spacing:1px">IDIRA</span></div><h2>Ricko Prayudha's Offline Workspace</h2><p class="muted">Selamat datang di rolebook belajar privat saya. Ini adalah <em>offline workspace</em> yang mengonsolidasikan catatan training, kurikulum simulasi, dan atlas pengetahuan Idira (CyberArk) L2 Support.</p><div class="version-warning" style="margin-top:20px;border-left-color:#eab308;background:rgba(234,179,8,.08)"><strong>DISCLAIMER & NON-AFFILIATION</strong><p style="color:var(--ink)">Aplikasi rolebook ini <strong>bukanlah produk resmi</strong> atau disediakan oleh Palo Alto Networks maupun CyberArk. Semua merek dagang, logo, dan material training adalah milik masing-masing perusahaan.</p><p style="color:var(--ink)">Aplikasi ini dibuat secara khusus (<em>Made by Ricko Prayudha</em>) semata-mata untuk mengelola catatan belajar dan tidak berisi informasi lisensi tertutup (raw training material/secret key).</p></div><button class="primary-btn" style="width:100%;margin-top:24px;font-size:1.1rem" id="btnEnterGate">Masuk ke Workspace / Enter Workspace</button></div></div>`}
function render(){if(!state.gatePassed){$('#viewRoot').innerHTML=renderGate();$('#btnEnterGate').addEventListener('click',()=>{state.gatePassed=true;save();render();});return;}shell();const fn={home:home,curriculum:curriculum,reader:reader,library:library,practice:practice,scenarios:scenarios,playbooks:playbooks,glossary:glossary,notes:notes,progress:progress}[state.view]||home;$('#viewRoot').innerHTML=fn();bind();if(state.view==='reader')bindReader()}
function head(k,t,d,a=''){return `<div class="page-head"><div><div class="eyebrow">${esc(k)}</div><h2>${esc(t)}</h2><p>${esc(d)}</p></div>${a?`<div class="page-actions">${a}</div>`:''}</div>`}
function metric(k,v,s){return `<div class="metric"><div class="metric-label">${esc(k)}</div><div class="metric-value">${esc(v)}</div><div class="metric-sub">${esc(s)}</div></div>`}
function status(m){if(complete(m.id))return `<span class="badge complete">✓ ${esc(copy().completed)}</span>`;if(state.activeModule===m.id)return `<span class="badge current">● ${esc(copy().continue)}</span>`;return `<span class="badge">${percent(m.id)}% ${esc(copy().read)}</span>`}
function resume(){return modules().find(m=>!complete(m.id)&&percent(m.id)>0)||modules().find(m=>!complete(m.id))||modules()[0]}
function home(){const ms=modules(),done=ms.filter(m=>complete(m.id)).length,avg=Math.round(ms.reduce((n,m)=>n+percent(m.id),0)/ms.length),a=state.quizAttempts,acc=a.length?Math.round(a.reduce((n,x)=>n+x.score,0)/a.reduce((n,x)=>n+x.total,0)*100):0,r=resume(),next=ms.find(m=>!complete(m.id)&&m.id!==r.id)||r;return `<section class="view">${head('IDIRA / L2 SUPPORT ? formerly CyberArk',copy().courseHome,state.lang==='id'?'Workspace belajar mengikuti urutan read → reason → practice → operate.':'A study workspace built around read → reason → practice → operate.',`<button class="primary-btn" data-action="open-module" data-module="${r.id}">${esc(percent(r.id)?copy().continue:copy().start)}</button><button class="quiet-btn" data-action="nav" data-view="curriculum">${esc(copy().viewAll)}</button>`)}<div class="metric-grid">${metric(copy().modules,`${done}/${ms.length}`,copy().completed)}${metric(copy().read,`${avg}%`,copy().courseHome)}${metric(copy().accuracy,`${acc}%`,`${a.length} ${copy().practice}`)}${metric(copy().labs,`${state.completedLabs.length}/${cases().length}`,copy().scenarios)}</div><div class="layout-2"><div class="card hero-card"><div class="hero-content"><span class="kicker">${esc(copy().resume)}</span><h3>${esc(title(r))}</h3><p class="muted">${esc(state.lang==='id'?r.lead:r.leadEn)}</p><div class="progress-track" style="background:rgba(255,255,255,.17)"><div class="progress-fill" style="width:${percent(r.id)}%;background:#62e4d1"></div></div><div class="split" style="margin-top:14px"><span class="small muted">${percent(r.id)}% · ${r.duration} ${esc(copy().duration)}</span><button class="primary-btn" data-action="open-module" data-module="${r.id}">${esc(copy().open)}</button></div></div></div><div class="card card-pad"><h3>${esc(copy().todayPlan)}</h3><p class="small">${esc(copy().planHint)}</p><div class="plan-list"><div class="plan-item"><span class="plan-num">1</span><div><strong>${esc(copy().open)}: ${esc(title(r))}</strong><span>${r.duration} ${esc(copy().duration)} · ${percent(r.id)}% ${esc(copy().read)}</span></div></div><div class="plan-item"><span class="plan-num">2</span><div><strong>${esc(copy().practice)}</strong><span>${esc(copy().practiceIntro)}</span></div></div><div class="plan-item"><span class="plan-num">3</span><div><strong>${esc(copy().nextModule)}: ${esc(title(next))}</strong><span>${esc(phase(next))}</span></div></div></div></div></div><div class="section-title"><h3>${esc(copy().learningPath)}</h3><span>${ms.length} ${esc(copy().modules)}</span></div><div class="layout-3">${COURSE.parts.slice(0,3).map(p=>{const pm=ms.filter(m=>m.part===p.id),d=pm.filter(m=>complete(m.id)).length;return `<div class="card card-pad"><div class="eyebrow">PART ${p.order}</div><h3 style="margin-top:6px">${esc(label(p.title))}</h3><p class="small">${esc(label(p.desc))}</p><div class="progress-track"><div class="progress-fill" style="width:${Math.round(d/pm.length*100)}%"></div></div><div class="small muted" style="margin-top:8px">${d}/${pm.length} ${esc(copy().completed)}</div></div>`}).join('')}</div><div class="section-title"><h3>${esc(copy().activity)}</h3><span>${state.studyDates.length} ${esc(copy().study)}</span></div><div class="card card-pad">${activities(6)}</div></section>`}
function activities(n=8){if(!state.activity.length)return `<div class="empty">${esc(copy().noActivity)}</div>`;return `<div class="list">${state.activity.slice(0,n).map(a=>`<div class="activity"><div class="activity-mark">${a.type==='quiz'?'✓':a.type==='lab'?'◈':a.type==='module'?'▦':'•'}</div><div><strong>${esc(a.text)}</strong><p>${esc(date(a.date))}</p></div></div>`).join('')}</div>`}
function refItems(value){return Array.isArray(value)?value:(value?[value]:[])}
function refDetail(entry){const sourceCards=(entry.sources||[]).map(id=>sourceById(id)).filter(Boolean);return `<div class="ref-entry"><div class="article-meta"><div><div class="eyebrow">${esc(entry.category)} / ${esc(entry.term)}</div><h3>${esc(label(entry.title))}</h3></div><div class="meta-chips"><span class="tag">${entry.readingTime||'N/A'} min</span><span class="tag">${esc(entry.lastReviewed||'N/A')}</span></div></div><div class="provenance-banner"><strong>${esc(state.lang==='id'?'Status sumber':'Source status')}</strong><p>${esc(label(window.REFERENCE_DATA.methodology))}</p><p class="small"><strong>${esc(state.lang==='id'?'Berlaku untuk':'Applies to')}:</strong> ${esc((entry.appliesTo||[]).join(' / '))}</p></div><section class="ref-section definition-lead"><h4>${esc(copy().what)}</h4><p>${esc(label(entry.what))} ${sourceMarks(entry.sources)}</p></section><section class="ref-section"><h4>${esc(copy().simple)}</h4><p>${esc(label(entry.simple))}</p></section><div class="longform">${refSections(entry)}</div><div class="evidence-grid"><section class="ref-section"><h4>${esc(state.lang==='id'?'Failure modes yang harus dikenali':'Failure modes to recognize')}</h4><ul>${refList(label(entry.failureModes))}</ul></section><section class="ref-section"><h4>${esc(state.lang==='id'?'Evidence minimum L2':'Minimum L2 evidence')}</h4><ul>${refList(label(entry.evidence))}</ul></section></div><section class="ref-section"><h4>${esc(copy().job)}</h4><ul>${refList(label(entry.job))}</ul><h4>${esc(copy().flow)}</h4><ul>${refList(label(entry.flow))}</ul><h4>${esc(copy().l2)}</h4><ul>${refList(label(entry.l2))}</ul></section><div class="version-warning"><strong>${esc(state.lang==='id'?'Catatan versi dan kewenangan':'Version and authorization note')}</strong><p>${esc(label(entry.versionNote))}</p><p>${refItems(label(entry.boundary)).map(item=>esc(item)).join('<br>')}</p></div><section class="ref-section"><h4>${esc(state.lang==='id'?'Sumber artikel':'Article sources')}</h4><div class="article-sources">${sourceCards.map(source=>`<button class="source-card-mini" data-action="open-source" data-source="${source.id}"><strong>[${esc(source.id)}]</strong><span>${esc(source.title)}</span><small>${esc(source.publisher)} / ${esc(source.type)}</small></button>`).join('')}</div></section><section class="ref-section"><h4>${esc(copy().related)}</h4><div class="module-tags">${(entry.related||[]).map(term=>`<button class="tag" data-action="open-term" data-term="${esc(term)}">${esc(term)}</button>`).join('')}</div></section></div>`}
function library(){const data=window.REFERENCE_DATA,q=runtime.refSearch.toLowerCase(),articleMode=runtime.libraryMode!=='sources',list=data.entries.filter(entry=>`${label(entry.title)} ${entry.term} ${label(entry.what)} ${label(entry.simple)} ${(entry.related||[]).join(' ')}`.toLowerCase().includes(q)),selected=list.find(entry=>entry.id===runtime.activeReference)||list[0];return `<section class="view">${head(copy().library,copy().library,copy().libraryIntro,`<div class="segmented"><button class="${articleMode?'active':''}" data-action="library-mode" data-mode="articles">${esc(state.lang==='id'?'Artikel':'Articles')}</button><button class="${!articleMode?'active':''}" data-action="library-mode" data-mode="sources">${esc(state.lang==='id'?'Bibliografi':'Bibliography')}</button></div>`)}<div class="card card-pad atlas-intro"><div class="eyebrow">START HERE / NO PREREQUISITE</div><h3>${esc(state.lang==='id'?'Peta komponen sebelum membaca artikel teknis':'Component map before technical reading')}</h3><p class="small">${esc(state.lang==='id'?'PVWA mengelola workflow. Vault/Safe menyimpan object dan authorization. PSM/PSMP memediasi session. CPM mengelola credential lifecycle. Audit menghubungkan semua aktivitas dengan evidence.':'PVWA manages workflows. The Vault/Safe stores objects and authorization. PSM/PSMP mediates sessions. CPM manages credential lifecycle. Audit links activities to evidence.')}</p><div class="atlas-map"><div><strong>1</strong><span>Identity / PVWA</span><small>Authentication / workflow</small></div><i>&rarr;</i><div><strong>2</strong><span>Vault / Safe</span><small>Object / authorization</small></div><i>&rarr;</i><div><strong>3</strong><span>PSM / PSMP</span><small>Session mediation</small></div><i>&rarr;</i><div><strong>4</strong><span>Target</span><small>Server / DB / device</small></div></div></div><div class="search-row"><label class="sr-only" for="refSearch">Search</label><input class="field" id="refSearch" value="${esc(runtime.refSearch)}" placeholder="${esc(articleMode?copy().librarySearch:(state.lang==='id'?'Cari source ID, publisher, atau judul...':'Search source ID, publisher, or title...'))}"></div>${articleMode?`<div class="ref-shell"><aside class="ref-list">${list.map(entry=>`<button class="ref-item ${entry.id===selected?.id?'active':''}" data-action="open-reference" data-reference="${entry.id}"><strong>${esc(label(entry.title))}</strong><span>${esc(entry.category)} / ${entry.readingTime||'N/A'} min</span></button>`).join('')}</aside><article class="card card-pad ref-detail">${selected?refDetail(selected):`<div class="empty">${esc(state.lang==='id'?'Tidak ada topik yang cocok.':'No matching topics.')}</div>`}</article></div>`:bibliography(runtime.refSearch)}</section>`}function curriculum(){const q=runtime.curriculumSearch.toLowerCase(),ms=modules();return `<section class="view">${head(copy().curriculum,copy().learningPath,state.lang==='id'?'Empat belas modul dari mental model PAM sampai ownership ticket L2.':'Fourteen modules from PAM mental models to L2 ticket ownership.',`<button class="quiet-btn" data-action="nav" data-view="practice">✓ ${esc(copy().practice)}</button>`)}<div class="search-row"><label class="sr-only" for="curriculumSearch">${esc(copy().search||'Search')}</label><input class="field" id="curriculumSearch" value="${esc(runtime.curriculumSearch)}" placeholder="${esc(state.lang==='id'?'Cari modul, tag, atau topik…':'Search modules, tags, or topics…')}"></div>${COURSE.parts.map(p=>{const list=ms.filter(m=>m.part===p.id&&(`${title(m)} ${state.lang==='id'?m.lead:m.leadEn} ${(m.tags||[]).join(' ')}`).toLowerCase().includes(q));if(!list.length)return '';const d=list.filter(m=>complete(m.id)).length;return `<div class="part-block"><div class="part-head"><div><div class="eyebrow">PART ${p.order} · ${d}/${list.length}</div><h3>${esc(label(p.title))}</h3><p>${esc(label(p.desc))}</p></div><span class="badge">${Math.round(d/list.length*100)}%</span></div><div class="module-grid">${list.map(m=>`<article class="module-card"><div class="module-top"><span class="module-no">M${String(m.order).padStart(2,'0')} · ${esc(phase(m))}</span>${status(m)}</div><h4>${esc(title(m))}</h4><p>${esc(state.lang==='id'?m.lead:m.leadEn)}</p><div class="module-tags">${(m.tags||[]).slice(0,4).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="module-foot"><span class="small muted">${m.duration} ${esc(copy().duration)}</span><button class="small-btn" data-action="open-module" data-module="${m.id}">${esc(copy().open)}</button></div></article>`).join('')}</div></div>`}).join('')}</section>`}
function buildLinks(html){
  const root=document.createElement('div');root.innerHTML=html;
  const entries=window.REFERENCE_DATA?.entries||[],seen=new Set(),blocked='a,button,code,pre,script,style,textarea';
  const terms=entries.flatMap(entry=>(entry.aliases||[entry.term]).map(alias=>({alias:String(alias).trim(),id:entry.id}))).filter(x=>x.alias.length>=3).sort((a,b)=>b.alias.length-a.alias.length);
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  const isWord=c=>!!c&&/[\p{L}\p{N}_]/u.test(c);
  nodes.forEach(node=>{
    if(!node.nodeValue?.trim()||node.parentElement?.closest(blocked))return;
    const text=node.nodeValue,lower=text.toLocaleLowerCase(),matches=[];
    terms.forEach(term=>{
      if(seen.has(term.id))return;const needle=term.alias.toLocaleLowerCase();let index=lower.indexOf(needle);
      while(index>=0){const before=text[index-1],after=text[index+needle.length];if(!isWord(before)&&!isWord(after)){matches.push({start:index,end:index+needle.length,id:term.id});break}index=lower.indexOf(needle,index+1)}
    });
    matches.sort((a,b)=>a.start-b.start||(b.end-b.start)-(a.end-a.start));const selected=[];let cursor=-1;
    matches.forEach(match=>{if(match.start>=cursor&&!seen.has(match.id)){selected.push(match);seen.add(match.id);cursor=match.end}});if(!selected.length)return;
    const frag=document.createDocumentFragment();cursor=0;selected.forEach(match=>{frag.append(text.slice(cursor,match.start));const button=document.createElement('button');button.type='button';button.className='inline-ref';button.dataset.action='open-reference';button.dataset.reference=match.id;button.textContent=text.slice(match.start,match.end);frag.append(button);cursor=match.end});frag.append(text.slice(cursor));node.replaceWith(frag);
  });
  return root.innerHTML;
}
function reader(){const m=mod(state.activeModule)||modules()[0],related=COURSE.guides[(m.order-1)%COURSE.guides.length],read=percent(m.id),ready=read>=85||complete(m.id),objectives=m[state.lang==='id'?'objId':'objEn']||[],ex=m.exercise,ev=[state.lang==='id'?'Mulai dari aktivitas yang gagal, bukan langsung menebak komponen.':'Start from the failed activity, not the component.',state.lang==='id'?'Kumpulkan scope, timestamp, last known good, recent change, dan exact error.':'Collect scope, timestamp, last known good, recent change, and exact error.',state.lang==='id'?'Pisahkan evidence dari hipotesis; perubahan produksi harus approved.':'Separate evidence from hypothesis; production changes require approval.'];return `<section class="view"><div class="reader-shell"><aside class="reader-side"><h3>${esc(copy().curriculum)}</h3><div class="reader-nav">${modules().map(x=>`<button class="${x.id===m.id?'active':''}" data-action="open-module" data-module="${x.id}"><strong>M${String(x.order).padStart(2,'0')} · ${percent(x.id)}%</strong>${esc(title(x))}</button>`).join('')}</div></aside><div class="reader-main card"><div class="reader-head"><div class="reader-head-top"><div><div class="eyebrow">${esc(phase(m))} · M${String(m.order).padStart(2,'0')}</div><h2>${esc(title(m))}</h2><p>${esc(state.lang==='id'?m.lead:m.leadEn)}</p></div><span class="badge ${complete(m.id)?'complete':''}">${complete(m.id)?'✓ '+esc(copy().markedComplete):read+'%'}</span></div><div class="reader-meta"><span class="tag">${m.duration} ${esc(copy().duration)}</span>${(m.tags||[]).map(t=>`<button class="tag" data-action="open-term" data-term="${esc(t)}">${esc(t)}</button>`).join('')}</div></div><div class="progress-track"><div class="progress-fill" id="readerProgress" style="width:${read}%"></div></div><div class="reader-scroll" id="readerScroll" tabindex="0">${readFirstPanel(m)}<div class="lesson-content">${buildLinks(state.lang==='id'?m.contentId:m.contentEn)}</div><div class="reader-extras"><div class="extra-card"><h3>☑ ${esc(copy().objectives)}</h3><ul class="check-list">${objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="extra-card"><h3>⌁ ${esc(copy().l2Lens)}</h3><ul>${ev.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div><div class="extra-card"><h3>⚙ ${esc(copy().exercise)}</h3><p class="small">${esc(label(ex.brief))}</p><ul>${(label(ex.deliverables)||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="notice" style="margin-top:13px">${esc(label(ex.safety))}</div></div><div class="reader-note"><label class="form-label">${esc(copy().moduleNote)}<textarea class="field" id="moduleNote" placeholder="${esc(copy().notesIntro)}">${esc(state.notes[m.id]||'')}</textarea></label></div><div class="gate ${ready?'ready':''}"><div><strong>${esc(copy().checkpoint)} · ${read}%</strong><span>${esc(ready?copy().checkpointReady:copy().checkpointLocked)}</span></div><div class="reader-controls"><button class="primary-btn" data-action="complete-module" data-module="${m.id}" ${ready?'':'aria-disabled="true"'}>${complete(m.id)?'✓ '+esc(copy().markedComplete):esc(copy().markComplete)}</button><button class="quiet-btn" data-action="start-module-quiz" data-module="${m.id}">✓ ${esc(copy().startPractice)}</button></div></div></div><div class="reader-footer"><div class="reader-controls"><button class="quiet-btn" data-action="prev-module" data-module="${m.id}" ${m.order===1?'disabled':''}>← ${esc(copy().previous)}</button><button class="quiet-btn" data-action="next-module" data-module="${m.id}" ${m.order===modules().length?'disabled':''}>${esc(copy().next)} →</button></div><button class="small-btn" data-action="open-guide" data-guide="${related.id}">${esc(copy().playbook)}: ${esc(label(related.title))}</button></div></div></div></section>`}
function bindReader(){const box=$('#readerScroll');if(!box)return;const update=()=>{const max=box.scrollHeight-box.clientHeight,ratio=max<=0?1:Math.min(1,box.scrollTop/max);if(ratio>(state.readProgress[state.activeModule]||0)){state.readProgress[state.activeModule]=ratio;$('#readerProgress').style.width=Math.round(ratio*100)+'%';if(ratio>=.85){const g=$('.gate');g?.classList.add('ready');if(g?.querySelector('span'))g.querySelector('span').textContent=copy().checkpointReady}save()}};box.addEventListener('scroll',update,{passive:true});setTimeout(update,100)}
function missed(){return state.quizAttempts[0]?.missed||[]}
function readiness(){const ms=modules(),read=ms.reduce((n,m)=>n+percent(m.id),0)/(ms.length*100),qa=state.quizAttempts,quiz=qa.length?qa.reduce((n,a)=>n+a.score,0)/qa.reduce((n,a)=>n+a.total,0):0,labs=state.completedLabs.length/cases().length,days=Math.min(state.studyDates.length/14,1);return Math.round((read*.35+quiz*.35+labs*.2+days*.1)*100)}
function practice(){if(runtime.quiz)return quizView();if(runtime.quizResult)return quizResult();const locked=!state.completedModules.length,weak=missed().length;return `<section class="view">${head(copy().practiceTitle,copy().practiceTitle,copy().practiceIntro,`<button class="quiet-btn" data-action="nav" data-view="scenarios">◈ ${esc(copy().scenarios)}</button>`)}<div class="layout-2"><div class="card card-pad"><div class="eyebrow">BANK ${questions().length} SOAL</div><h3 style="margin-top:6px">${esc(copy().practiceTitle)}</h3><p class="small">${esc(copy().planHint)}</p>${locked?`<div class="notice" style="margin:16px 0">${esc(copy().lockedQuiz)}</div>`:''}<div class="form-grid" style="margin-top:20px"><label class="form-label">${esc(copy().scope)}<select class="field" id="quizScope" ${locked?'disabled':''}><option value="all">${esc(copy().all)}</option><option value="current">${esc(copy().current)}</option><option value="weak" ${weak?'':'disabled'}>${esc(copy().weak)} (${weak})</option></select></label><label class="form-label">${esc(copy().count)}<select class="field" id="quizCount" ${locked?'disabled':''}><option value="5">5</option><option value="10">10</option><option value="20">20</option><option value="all">${questions().length}</option></select></label></div><div style="margin-top:17px"><div class="form-label">${esc(copy().mode)}</div><div class="segmented" id="quizMode"><button class="active" data-mode="practice">${esc(copy().practiceMode)}</button><button data-mode="exam">${esc(copy().examMode)}</button></div></div><div class="page-actions" style="margin-top:22px"><button class="primary-btn" data-action="start-quiz" ${locked?'disabled':''}>${esc(copy().startQuiz)}</button><button class="quiet-btn" data-action="retry-missed" ${!weak?'disabled':''}>${esc(copy().retryMissed)}</button></div></div><div class="card card-pad"><h3>${esc(copy().readiness)}</h3><p class="small">${esc(state.lang==='id'?'Menggabungkan bacaan, quiz, lab, dan konsistensi belajar.':'Combines reading, quizzes, labs, and study consistency.')}</p><div class="result-score" style="font-size:2.5rem">${readiness()}%</div><div class="progress-track"><div class="progress-fill" style="width:${readiness()}%"></div></div><div class="section-title"><h3>${esc(copy().retryMissed)}</h3></div><p class="small muted">${weak?`${weak} ${esc(copy().question)}.`:esc(copy().noMissed)}</p><div class="notice">${esc(copy().referenceNote)}</div></div></div><div class="section-title"><h3>${esc(copy().activity)}</h3></div><div class="card card-pad">${state.quizAttempts.length?`<div class="activity-table">${state.quizAttempts.slice(0,8).map(a=>`<div class="activity-row"><span>${esc(date(a.date))}</span><strong>${a.score}/${a.total} · ${a.mode}</strong><span>${esc(a.moduleIds.join(', '))}</span></div>`).join('')}</div>`:`<div class="empty">${esc(copy().noActivity)}</div>`}</div></section>`}
function shuffle(a){const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
function startQuiz(scope='all',count='10',mode='practice',custom=null){let pool=custom||questions();if(scope==='current')pool=pool.filter(q=>q.m===state.activeModule);if(scope==='weak'){const ids=new Set(missed());pool=pool.filter(q=>ids.has(q.q?.id||q.q?.en))}pool=shuffle(pool);if(count!=='all')pool=pool.slice(0,Number(count));if(!pool.length){toast(copy().noMissed,'warn');return}runtime.quiz={pool,index:0,selected:null,checked:false,mode,answers:[],startedAt:Date.now()};state.view='practice';render()}
function quizView(){const x=runtime.quiz,q=x.pool[x.index],sel=x.selected,checked=x.checked,correct=checked&&q.c[sel]?.correct;return `<section class="view">${head(copy().practiceTitle,`${copy().question} ${x.index+1} ${copy().of} ${x.pool.length}`,x.mode==='exam'?copy().examMode:copy().practiceMode)}<div class="card card-pad question-card"><div class="quiz-head"><strong>${esc(title(mod(q.m)))}</strong><span>${Math.round(x.index/x.pool.length*100)}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.round((x.index+1)/x.pool.length*100)}%"></div></div><h3>${esc(label(q.q))}</h3><div class="choice-grid" role="radiogroup">${q.c.map((c,i)=>`<button class="choice ${sel===i?'selected ':''}${checked&&c.correct?'correct ':''}${checked&&sel===i&&!c.correct?'wrong ':''}" data-action="quiz-choice" data-index="${i}" role="radio" aria-checked="${sel===i}" ${checked?'disabled':''}><span class="choice-indicator">${checked&&c.correct?'✓':checked&&sel===i&&!c.correct?'×':String.fromCharCode(65+i)}</span><span>${esc(label(c))}</span></button>`).join('')}</div>${checked&&x.mode==='practice'?`<div class="feedback ${correct?'good':'bad'}"><strong>${correct?'✓ '+esc(copy().correct):'× '+esc(copy().incorrect)}</strong><p>${esc(label(q.e))}</p></div>`:''}<div class="quiz-actions"><button class="quiet-btn" data-action="quit-quiz">${esc(copy().practice)}</button>${!checked?`<button class="primary-btn" data-action="check-quiz">${esc(copy().check)}</button>`:`<button class="primary-btn" data-action="next-quiz">${x.index===x.pool.length-1?esc(copy().finish):esc(copy().nextQuestion)}</button>`}</div></div></section>`}
function finishQuiz(){const x=runtime.quiz,score=x.answers.filter(a=>a.correct).length,m=x.answers.filter(a=>!a.correct).map(a=>a.questionId),a={id:String(Date.now()),date:new Date().toISOString(),score,total:x.pool.length,mode:x.mode,moduleIds:unique(x.pool.map(q=>q.m)),missed:m,duration:Math.round((Date.now()-x.startedAt)/1000)};state.quizAttempts.unshift(a);activity('quiz',`${score}/${x.pool.length} ${x.mode} completed`);runtime.quiz=null;runtime.quizResult=a;render()}
function quizResult(){const a=runtime.quizResult,p=Math.round(a.score/a.total*100);return `<section class="view">${head(copy().quizComplete,copy().quizComplete,state.lang==='id'?'Gunakan hasil ini untuk memilih modul yang perlu diulang.':'Use this result to choose lessons for another pass.',`<button class="quiet-btn" data-action="new-quiz">${esc(copy().newQuiz)}</button>`)}<div class="layout-2"><div class="card card-pad"><div class="eyebrow">${a.mode.toUpperCase()}</div><div class="result-score">${p}%</div><div class="result-label">${a.score} ${esc(copy().correct)} ${esc(copy().of)} ${a.total}</div><div class="result-grid"><div class="result-stat"><strong>${a.score}</strong><span>${esc(copy().correct)}</span></div><div class="result-stat"><strong>${a.total-a.score}</strong><span>${esc(copy().incorrect)}</span></div><div class="result-stat"><strong>${a.duration}s</strong><span>duration</span></div></div><p class="small">${esc(p>=80?(state.lang==='id'?'Pemahaman cukup kuat. Jelaskan kembali alasan tiap jawaban tanpa melihat pembahasan.':'Solid result. Explain each answer without the explanation.'):(state.lang==='id'?'Buka modul terkait, lalu ulangi soal yang salah.':'Open the related lessons, then retry missed questions.'))}</p><div class="page-actions"><button class="primary-btn" data-action="retry-attempt" ${a.missed.length?'':'disabled'}>${esc(copy().retryMissed)}</button><button class="quiet-btn" data-action="new-quiz">${esc(copy().newQuiz)}</button></div></div><div class="card card-pad"><h3>${esc(copy().review)}</h3>${a.missed.length?`<div class="list">${a.missed.map(id=>{const q=questions().find(x=>(x.q?.id||x.q?.en)===id);return q?`<div class="activity"><div class="activity-mark">×</div><div><strong>${esc(label(q.q))}</strong><p>${esc(title(mod(q.m)))}</p></div></div>`:''}).join('')}</div>`:`<div class="empty">${esc(copy().correct)} — ${state.lang==='id'?'tidak ada soal salah.':'no missed questions.'}</div>`}</div></div></section>`}
function scenarios(){const c=caseData(state.activeCase),d=c[state.lang==='id'?'id':'en'],result=runtime.caseResult;return `<section class="view">${head(copy().scenarioTitle,copy().scenarioTitle,copy().scenarioIntro,`<button class="primary-btn" data-action="random-case">⤨ ${esc(copy().random)}</button>`)}<div class="case-shell"><aside class="case-list">${cases().map(x=>{const z=x[state.lang==='id'?'id':'en'];return `<button class="${x.key===c.key?'active':''}" data-action="open-case" data-case="${x.key}"><strong>${esc(z.title)}</strong><span>${esc(z.cat)}</span></button>`}).join('')}</aside><article class="card card-pad case-detail"><div class="eyebrow">${esc(d.cat)}</div><h3>${esc(d.title)}</h3><p>${esc(d.desc)}</p><h4>${esc(copy().evidenceAvailable)}</h4><div class="evidence">${d.evi.map(x=>`<div class="evidence-item">${esc(x)}</div>`).join('')}</div><h4>${esc(copy().task)}</h4><p class="small">${esc(copy().chooseStep)}</p><div class="choice-grid">${d.choices.map((x,i)=>`<button class="choice ${result?.caseId===c.key&&result.choice===i?(i===d.correct?'correct':'wrong'):''}" data-action="case-choice" data-index="${i}"><span class="choice-indicator">${String.fromCharCode(65+i)}</span><span>${esc(x)}</span></button>`).join('')}</div>${result?.caseId===c.key?`<div class="feedback ${result.correct?'good':'bad'}"><strong>${result.correct?'✓ '+esc(copy().correct):'× '+esc(copy().incorrect)}</strong><p>${esc(result.correct?(state.lang==='id'?'Pilihan ini menjaga scope sempit dan evidence-first.':'This keeps scope narrow and evidence-first.'):(state.lang==='id'?'Pilihan ini melompat ke tindakan sebelum isolasi cukup.':'This jumps to action before isolation is sufficient.'))}</p></div><h4>${esc(copy().investigation)}</h4><ol class="investigation">${d.invest.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="notice"><strong>${esc(copy().avoid)}:</strong> ${esc(d.avoid)}<br><strong>${esc(copy().escalate)}:</strong> ${esc(d.esc)}</div>`:''}</article></div></section>`}
const asList=v=>Array.isArray(v)?v:(v?[v]:[]);
function playbooks(){const q=runtime.guideSearch.toLowerCase(),list=COURSE.guides.filter(g=>(`${label(g.title)} ${g.group} ${label(g.trigger)}`).toLowerCase().includes(q)),g=guide(state.activeGuide),steps=asList(label(g.steps)),ev=asList(label(g.evidence));return `<section class="view">${head(copy().playbookTitle,copy().playbookTitle,copy().playbookIntro)}<div class="search-row"><label class="sr-only" for="guideSearch">Search</label><input class="field" id="guideSearch" value="${esc(runtime.guideSearch)}" placeholder="${state.lang==='id'?'Cari playbook…':'Search playbooks…'}"></div><div class="guide-shell"><aside class="guide-list">${list.map(x=>`<button class="${x.id===g.id?'active':''}" data-action="open-guide" data-guide="${x.id}"><strong>${esc(label(x.title))}</strong><span>${esc(x.group)}</span></button>`).join('')}</aside><article class="card card-pad guide-detail"><div class="eyebrow">${esc(g.group)}</div><h3>${esc(label(g.title))}</h3><h4>${esc(copy().trigger)}</h4><p class="small">${esc(label(g.trigger))}</p><h4>${esc(copy().steps)}</h4><ol class="step-list">${steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h4>${esc(copy().evidencePack)}</h4><div class="evidence">${ev.map(x=>`<div class="evidence-item">${esc(x)}</div>`).join('')}</div><h4>${esc(copy().avoid)}</h4><div class="notice">${esc(label(g.avoid))}</div><div class="page-actions" style="margin-top:18px"><button class="primary-btn" data-action="copy-template" data-guide="${g.id}">▣ Copy ticket template</button></div></article></div></section>`}
function glossary(){const q=runtime.termSearch.toLowerCase(),list=COURSE.glossary.filter(g=>`${g.term} ${label(g.def)}`.toLowerCase().includes(q));return `<section class="view">${head(copy().glossaryTitle,copy().glossaryTitle,copy().glossaryIntro,`<span class="badge current">${state.glossarySeen.length}/${COURSE.glossary.length} ${esc(copy().known)}</span>`)}<div class="search-row"><label class="sr-only" for="termSearch">Search</label><input class="field" id="termSearch" value="${esc(runtime.termSearch)}" placeholder="${state.lang==='id'?'Cari istilah…':'Search terms…'}"></div><div class="glossary-grid">${list.map(g=>{const rev=runtime.glossaryReveal.has(g.term),known=state.glossarySeen.includes(g.term);return `<article class="term-card ${rev?'revealed':''}"><button data-action="reveal-term" data-term="${esc(g.term)}"><strong>${esc(g.term)}</strong><p>${rev?esc(label(g.def)):esc(copy().recall)+' — '+(state.lang==='id'?'klik untuk lihat definisi':'click to reveal')}</p></button><div class="term-actions"><span class="known">${known?'✓ '+esc(copy().known):''}</span><button class="small-btn" data-action="toggle-known" data-term="${esc(g.term)}">${known?esc(copy().unmarkKnown):esc(copy().markKnown)}</button></div></article>`}).join('')}</div>${list.length?'':`<div class="empty">No matching terms.</div>`}</section>`}
function notes(){const active=runtime.noteModule,value=active==='journal'?state.journal:(state.notes[active]||'');return `<section class="view">${head(copy().notesTitle,copy().notesTitle,copy().notesIntro,`<button class="primary-btn" data-action="save-notes">✓ ${esc(copy().save)}</button>`)}<div class="notebook-shell"><aside class="note-tabs"><button class="${active==='journal'?'active':''}" data-action="open-note" data-note="journal"><strong>${esc(copy().journal)}</strong><span>${state.journal.length} chars</span></button>${modules().map(m=>`<button class="${active===m.id?'active':''}" data-action="open-note" data-note="${m.id}"><strong>M${String(m.order).padStart(2,'0')} · ${esc(title(m))}</strong><span>${(state.notes[m.id]||'').length} chars</span></button>`).join('')}</aside><div class="card card-pad"><label class="form-label">${esc(active==='journal'?copy().journal:title(mod(active)))}<textarea class="field" id="noteEditor" placeholder="${esc(copy().notesIntro)}">${esc(value)}</textarea></label><div class="notice" style="margin-top:14px">${esc(copy().notesIntro)}</div></div></div></section>`}
function progress(){const ms=modules(),done=ms.filter(m=>complete(m.id)).length,a=state.quizAttempts,acc=a.length?Math.round(a.reduce((n,x)=>n+x.score,0)/a.reduce((n,x)=>n+x.total,0)*100):0,heat=Array.from({length:28},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(27-i));const k=d.toISOString().slice(0,10);return `<span class="heat-day ${state.studyDates.includes(k)?'active':''} ${k===today()?'today':''}" title="${k}"></span>`}).join('');return `<section class="view">${head(copy().progressTitle,copy().progressTitle,copy().progressIntro,`<button class="primary-btn" data-action="export-json">⇩ ${esc(copy().exportJson)}</button>`)}<div class="metric-grid">${metric(copy().modulesComplete,`${done}/${ms.length}`,copy().completed)}${metric(copy().quizAccuracy,`${acc}%`,`${a.length} attempts`)}${metric(copy().labComplete,`${state.completedLabs.length}/${cases().length}`,copy().scenarios)}${metric(copy().readiness,`${readiness()}%`,copy().studyDays+': '+state.studyDates.length)}</div><div class="layout-2"><div class="card card-pad"><h3>${esc(copy().studyDays)}</h3><p class="small">${esc(copy().planHint)}</p><div class="heatmap" style="margin-top:16px">${heat}</div><div class="section-title"><h3>${esc(copy().activity)}</h3></div>${activities(12)}</div><div class="card card-pad"><h3>${esc(copy().settings)}</h3><p class="small">${esc(copy().progressIntro)}</p><div class="list" style="margin-top:15px"><button class="quiet-btn" data-action="import-json">⇧ ${esc(copy().importJson)}</button><button class="quiet-btn" data-action="export-report">▤ ${esc(copy().report)}</button><button class="danger-btn" data-action="reset-progress">⌫ ${esc(copy().reset)}</button></div><div class="notice" style="margin-top:18px">${esc(copy().referenceNote)}</div></div></div><div class="section-title"><h3>${esc(copy().curriculum)}</h3></div><div class="card card-pad"><div class="list">${ms.map(m=>`<div><div class="split"><strong class="small">M${String(m.order).padStart(2,'0')} · ${esc(title(m))}</strong><span class="small muted">${complete(m.id)?'✓ ':''}${percent(m.id)}%</span></div><div class="progress-track" style="margin-top:7px"><div class="progress-fill" style="width:${percent(m.id)}%"></div></div></div>`).join('')}</div></div><div class="section-title"><h3>${esc(copy().references)}</h3></div><div class="card card-pad"><p class="small">${esc(copy().referenceNote)}</p><div class="page-actions"><a class="small-btn" href="https://docs.cyberark.com/" target="_blank" rel="noreferrer">CyberArk Documentation ↗</a><a class="small-btn" href="https://www.cyberark.com/resources/" target="_blank" rel="noreferrer">CyberArk Resources ↗</a><a class="small-btn" href="https://www.w3.org/WAI/standards-guidelines/wcag/" target="_blank" rel="noreferrer">WCAG ↗</a></div></div></section>`}
function bind(){const c=$('#curriculumSearch');if(c)c.addEventListener('input',e=>{runtime.curriculumSearch=e.target.value;render();setTimeout(()=>{$('#curriculumSearch')?.focus();$('#curriculumSearch')?.setSelectionRange(runtime.curriculumSearch.length,runtime.curriculumSearch.length)},0)});const ref=$('#refSearch');if(ref)ref.addEventListener('input',e=>{runtime.refSearch=e.target.value;render();setTimeout(()=>{$('#refSearch')?.focus();$('#refSearch')?.setSelectionRange(runtime.refSearch.length,runtime.refSearch.length)},0)});const g=$('#guideSearch');if(g)g.addEventListener('input',e=>{runtime.guideSearch=e.target.value;render();setTimeout(()=>$('#guideSearch')?.focus(),0)});const t=$('#termSearch');if(t)t.addEventListener('input',e=>{runtime.termSearch=e.target.value;render();setTimeout(()=>$('#termSearch')?.focus(),0)});const n=$('#noteEditor');if(n)n.addEventListener('input',e=>{if(runtime.noteModule==='journal')state.journal=e.target.value;else state.notes[runtime.noteModule]=e.target.value;save()});const m=$('#moduleNote');if(m)m.addEventListener('input',e=>{state.notes[state.activeModule]=e.target.value;save()});const mode=$('#quizMode');if(mode)mode.addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(!b)return;$$('#quizMode [data-mode]').forEach(x=>x.classList.toggle('active',x===b))})}
function copyGuide(id){const g=guide(id),text=[label(g.title),`Trigger: ${label(g.trigger)}`,`${copy().steps}:`,...asList(label(g.steps)).map((x,i)=>`${i+1}. ${x}`),`${copy().evidencePack}:`,...asList(label(g.evidence)).map(x=>`- ${x}`),`${copy().avoid}: ${label(g.avoid)}`].join('\n');navigator.clipboard?.writeText(text).then(()=>toast(state.lang==='id'?'Template ticket berhasil dicopy.':'Ticket template copied.')).catch(()=>toast(state.lang==='id'?'Browser tidak mengizinkan clipboard.':'Clipboard permission was denied.','warn'))}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function report(){const lines=[`# CyberArk L2 Rolebook — ${new Date().toISOString()}`,'',`- Language: ${state.lang}`,`- Modules complete: ${state.completedModules.length}/${modules().length}`,`- Reading average: ${Math.round(modules().reduce((n,m)=>n+percent(m.id),0)/modules().length)}%`,`- Readiness: ${readiness()}%`,`- Quiz attempts: ${state.quizAttempts.length}`,`- Labs complete: ${state.completedLabs.length}/${cases().length}`,`- Study days: ${state.studyDates.length}`,'','## Recent activity',...state.activity.slice(0,20).map(a=>`- ${date(a.date)} — ${a.text}`),'','## Learning journal',state.journal||'—'];download(`idira-rolebook-report-${today()}.md`,lines.join('\n'),'text/markdown')}
function importFile(file){const r=new FileReader();r.onload=()=>{try{const raw=JSON.parse(r.result);if(!raw||typeof raw!=='object'||(!raw.version&&!raw.completedModules))throw Error();state=merge(raw);state.view='progress';save();render();toast(state.lang==='id'?'Progress berhasil diimport.':'Progress imported successfully.')}catch{toast(state.lang==='id'?'File progress tidak valid.':'Invalid progress file.','warn')}};r.readAsText(file)}
function reset(){if(!confirm(copy().resetConfirm))return;const lang=state.lang,theme=state.theme;state=clone(DEFAULT);state.lang=lang;state.theme=theme;runtime={refSearch:'',activeReference:'pam',quiz:null,quizResult:null,caseResult:null,glossaryReveal:new Set(),curriculumSearch:'',guideSearch:'',termSearch:'',noteModule:'journal'};save();render();toast(state.lang==='id'?'Progress direset.':'Progress reset.','warn')}
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
  if(a==='nav')nav(b.dataset.view);
  if(a==='library-mode'){runtime.libraryMode=b.dataset.mode;runtime.refSearch='';state.view='library';render();setTimeout(()=>$('#refSearch')?.focus(),30)}if(a==='open-source'){runtime.libraryMode='sources';runtime.activeSource=b.dataset.source;runtime.refSearch='';state.view='library';render();setTimeout(()=>{const e=$('#source-'+b.dataset.source);if(e)e.scrollIntoView({behavior:'smooth',block:'start'})},100)}if(a==='open-reference'){runtime.libraryMode='articles';const item=window.REFERENCE_DATA.entries.find(x=>x.id===b.dataset.reference);runtime.activeReference=item?.id||'pam';runtime.refSearch='';state.view='library';render();setTimeout(()=>$('#refSearch')?.focus(),30)}
  if(a==='lang'){state.lang=b.dataset.lang;prefs();render();activity('settings',copy().langChanged||'Language changed')}
  if(a==='focus'){state.focus=!state.focus;prefs();save()}
  if(a==='theme'){state.theme=state.theme==='dark'?'light':'dark';prefs();save()}
  if(a==='open-module'){state.activeModule=b.dataset.module;state.view='reader';render()}
  if(a==='prev-module'||a==='next-module'){const m=mod(b.dataset.module),ms=modules(),n=ms[m.order-1+(a==='next-module'?1:-1)];if(n){state.activeModule=n.id;render()}}
  if(a==='complete-module'){
    const id=b.dataset.module;if((state.readProgress[id]||0)>=.85||complete(id)){
      state.completedModules=unique([...state.completedModules,id]);state.readProgress[id]=1;
      activity('module',`${title(mod(id))} completed`);render();toast(copy().markedComplete)
    }else toast(copy().checkpointLocked,'warn')
  }
  if(a==='start-module-quiz'){const id=b.dataset.module;if((state.readProgress[id]||0)>=.85||complete(id))startQuiz('current','10','practice');else toast(copy().checkpointLocked,'warn')}
  if(a==='start-quiz'){startQuiz($('#quizScope')?.value||'all',$('#quizCount')?.value||'10',$('#quizMode .active')?.dataset.mode||'practice')}
  if(a==='retry-missed'){const qids=missed();if(qids.length){const pool=questions().filter(q=>qids.includes(q.q?.id||q.q?.en));startQuiz('all',qids.length,'practice',pool)}}
  if(a==='retry-attempt'){const qids=runtime.quizResult?.missed||[],pool=questions().filter(q=>qids.includes(q.q?.id||q.q?.en));if(pool.length)startQuiz('all',pool.length,'practice',pool)}
  if(a==='new-quiz'){runtime.quizResult=null;state.view='practice';render()}
  if(a==='quit-quiz'){runtime.quiz=null;state.view='practice';render()}
  if(a==='quiz-choice'&&!runtime.quiz?.checked){runtime.quiz.selected=Number(b.dataset.index);render()}
  if(a==='check-quiz'){
    if(runtime.quiz?.selected===null||runtime.quiz?.selected===undefined){toast(copy().choose,'warn');return}
    const q=runtime.quiz.pool[runtime.quiz.index],correct=!!q.c[runtime.quiz.selected]?.correct;
    runtime.quiz.answers.push({questionId:q.q?.id||q.q?.en,correct,selected:runtime.quiz.selected});
    runtime.quiz.checked=true;render()
  }
  if(a==='next-quiz'){if(runtime.quiz.index===runtime.quiz.pool.length-1)finishQuiz();else{runtime.quiz.index++;runtime.quiz.selected=null;runtime.quiz.checked=false;render()}}
  if(a==='open-case'){state.activeCase=b.dataset.case;runtime.caseResult=null;render()}
  if(a==='random-case'){const ids=cases().map(x=>x.key);state.activeCase=ids[Math.floor(Math.random()*ids.length)];runtime.caseResult=null;render()}
  if(a==='case-choice'){
    const c=caseData(state.activeCase),d=c[state.lang==='id'?'id':'en'],choice=Number(b.dataset.index),correct=choice===d.correct;
    runtime.caseResult={caseId:c.key,choice,correct};state.labAttempts.unshift({caseId:c.key,choice,correct,date:new Date().toISOString()});
    state.completedLabs=unique([...state.completedLabs,c.key]);activity('lab',`${d.title} ${correct?'completed':'reviewed'}`);render()
  }
  if(a==='open-guide'){state.activeGuide=b.dataset.guide;state.view='playbooks';render()}
  if(a==='copy-template')copyGuide(b.dataset.guide);
  if(a==='open-term'){runtime.libraryMode='articles';const needle=(b.dataset.term||'').toLowerCase(),item=window.REFERENCE_DATA.entries.find(x=>x.term.toLowerCase()===needle||x.id.toLowerCase()===needle);if(item){runtime.activeReference=item.id;runtime.refSearch='';state.view='library';render()}else{runtime.termSearch=b.dataset.term;state.view='glossary';runtime.glossaryReveal.add(b.dataset.term);render()}}
  if(a==='reveal-term'){runtime.glossaryReveal.add(b.dataset.term);render()}
  if(a==='toggle-known'){const t=b.dataset.term;if(state.glossarySeen.includes(t))state.glossarySeen=state.glossarySeen.filter(x=>x!==t);else state.glossarySeen.push(t);save();render()}
  if(a==='open-note'){runtime.noteModule=b.dataset.note;render();setTimeout(()=>$('#noteEditor')?.focus(),50)}
  if(a==='save-notes'){save();toast(copy().saved)}
  if(a==='export-json')download(`cyberark-rolebook-progress-${today()}.json`,JSON.stringify(state,null,2));
  if(a==='import-json')$('#importFile')?.click();
  if(a==='export-report')report();
  if(a==='reset-progress')reset();
});
$('#importFile')?.addEventListener('change',e=>{if(e.target.files[0])importFile(e.target.files[0]);e.target.value=''});
window.addEventListener('beforeunload',()=>{try{localStorage.setItem('cyberark-l2-rolebook-v4',JSON.stringify(state))}catch{}});
load();














